package kr.co.donationserver.command;
import kr.co.donationserver.data.*;import kr.co.donationserver.service.EconomyService;import kr.co.donationserver.util.Texts;import net.minecraft.command.*;import net.minecraft.entity.player.EntityPlayerMP;import net.minecraft.server.MinecraftServer;
public class EconomyAdminCommand extends CommandBase {public String getName(){return "경제관리";}public int getRequiredPermissionLevel(){return 2;}public String getUsage(ICommandSender s){return "/경제관리 <돈추가 플레이어 금액|돈설정 플레이어 금액|거래소설정>";}public void execute(MinecraftServer server,ICommandSender sender,String[] a)throws CommandException{if(a.length==1&&a[0].equals("거래소설정")){EntityPlayerMP p=getCommandSenderAsPlayer(sender);DonationData d=DonationData.get(p.world);d.trade=LocationData.of(p);d.markDirty();p.sendMessage(Texts.text("&a거래소 위치를 설정했습니다."));return;}if(a.length==3&&(a[0].equals("돈추가")||a[0].equals("돈설정"))){EntityPlayerMP t=getPlayer(server,sender,a[1]);long n=parseLong(a[2],0,Long.MAX_VALUE);DonationData d=DonationData.get(t.world);PlayerData pd=d.player(t.getUniqueID());pd.balance=a[0].equals("돈설정")?n:(Long.MAX_VALUE-pd.balance<n?Long.MAX_VALUE:pd.balance+n);d.markDirty();EconomyService.sync(t);sender.sendMessage(Texts.text("&a"+t.getName()+" 잔액: "+Texts.money(pd.balance)));return;}throw new WrongUsageException(getUsage(sender));}}
